  // GRAPHENE Button
  btnGraphene.addEventListener('click', () => {
    grapheneMode = !grapheneMode;
    if (grapheneMode) {
      elementCloudMode = false;
      dataTableMode = false;
      if (superMode) toggleSuperMode(false);
      btnElementCloud.classList.remove('active');
      btnElementCloud.setAttribute('fill', '#1a1a1f');
      btnDataTable.classList.remove('active');
      btnDataTable.setAttribute('fill', '#1a1a1f');

      btnGraphene.classList.add('active');
      btnGraphene.setAttribute('fill', '#00ffaa');
      grapheneSliderPanel.style.display = '';
      lblGrapheneScale.style.display = '';
    } else {
      btnGraphene.classList.remove('active');
      btnGraphene.setAttribute('fill', '#1a1a1f');
      grapheneSliderPanel.style.display = 'none';
      lblGrapheneScale.style.display = 'none';
    }
    updateUI(true);
  });

  // SUPERPOSITION Button
  btnSuper.addEventListener('click', (e) => {
    e.stopPropagation();
    toggleSuperMode();
  });

  // Super pause button
  superPauseBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    superPaused = !superPaused;
    if (superPaused) {
      stopSuperAnimation();
    } else {
      startSuperAnimation();
    }
  });

  // ===== THETA SLIDER =====
  const THETA_MIN_X = 20;
  const THETA_MAX_X = 410;
  const THETA_TRACK_Y = 76;
  let isThetaDragging = false;

  function updateThetaFromClientX(clientX) {
    const svgEl = document.getElementById('viewport');
    const pt = svgEl.createSVGPoint();
    pt.x = clientX;
    pt.y = 0;
    const svgP = pt.matrixTransform(svgEl.getScreenCTM().inverse());
    let localX = svgP.x - 250;
    localX = Math.max(THETA_MIN_X, Math.min(THETA_MAX_X, localX));
    const percent = (localX - THETA_MIN_X) / (THETA_MAX_X - THETA_MIN_X);
    superMixTheta = percent * (Math.PI / 2);
    superThetaThumb.setAttribute('cx', localX);
    superThetaValue.textContent = (superMixTheta * 180 / Math.PI).toFixed(0) + '°';
    superThetaEl.textContent = (superMixTheta * 180 / Math.PI).toFixed(0) + '°';
    if (superMode && !superPaused) {
      // Will be picked up by animation loop
    } else if (superMode) {
      superApplyTime();
      scheduleDraw();
    }
  }

  superThetaThumb.addEventListener('pointerdown', (e) => {
    e.stopPropagation();
    isThetaDragging = true;
    superThetaThumb.setPointerCapture(e.pointerId);
  });
  superThetaThumb.addEventListener('pointermove', (e) => {
    if (!isThetaDragging) return;
    e.stopPropagation();
    updateThetaFromClientX(e.clientX);
  });
  superThetaThumb.addEventListener('pointerup', (e) => {
    if (!isThetaDragging) return;
    e.stopPropagation();
    isThetaDragging = false;
    superThetaThumb.releasePointerCapture(e.pointerId);
  });

  superControlPanel.addEventListener('pointerdown', (e) => {
    if (e.target === superThetaThumb) return;
    if (e.target === superPauseBtn || superPauseBtn.contains(e.target)) return;
    if (e.target === superCycleB || superCycleB.contains(e.target)) return;
    const svgEl = document.getElementById('viewport');
    const pt = svgEl.createSVGPoint();
    pt.x = e.clientX;
    pt.y = e.clientY;
    const svgP = pt.matrixTransform(svgEl.getScreenCTM().inverse());
    const localX = svgP.x - 250;
    const localY = svgP.y - 560;
    if (localY >= THETA_TRACK_Y - 8 && localY <= THETA_TRACK_Y + 16 && localX >= THETA_MIN_X && localX <= THETA_MAX_X) {
      updateThetaFromClientX(e.clientX);
    }
  });

  // ===== CYCLE STATE B =====
  superCycleB.addEventListener('click', (e) => {
    e.stopPropagation();
    superBIdx = (superBIdx + 1) % SUPER_B_PRESETS.length;
    superStateB = Object.assign({}, SUPER_B_PRESETS[superBIdx]);
    if (superMode) generateSuperpositionCloud(scheduleDraw);
  });

  // ===== GRAPHENE SLIDER DRAG LOGIC =====
  let isSliderDragging = false;
  const SLIDER_MIN_X = 20;
  const SLIDER_MAX_X = 410;

  function updateGrapheneSlider(clientX) {
    const svgEl = document.getElementById('viewport');
    const pt = svgEl.createSVGPoint();
    pt.x = clientX;
    pt.y = 0;
    const svgP = pt.matrixTransform(svgEl.getScreenCTM().inverse());

    let localX = svgP.x - 250;
    localX = Math.max(SLIDER_MIN_X, Math.min(SLIDER_MAX_X, localX));

    const percent = (localX - SLIDER_MIN_X) / (SLIDER_MAX_X - SLIDER_MIN_X);
    const newRings = Math.round(1 + percent * 9);

    if (newRings !== grapheneRings) {
      grapheneRings = newRings;
      grapheneSliderValue.textContent = grapheneRings;
      grapheneSliderThumb.setAttribute('cx', localX);
      lblGrapheneScale.textContent = 'Graphene: Rings = ' + grapheneRings;
      if (grapheneMode) generateCloud(scheduleDraw);
    }
  }

  grapheneSliderThumb.addEventListener('pointerdown', (e) => {
    e.stopPropagation();
    isSliderDragging = true;
    grapheneSliderThumb.setPointerCapture(e.pointerId);
  });

  grapheneSliderThumb.addEventListener('pointermove', (e) => {
    if (!isSliderDragging) return;
    e.stopPropagation();
    updateGrapheneSlider(e.clientX);
  });

  grapheneSliderThumb.addEventListener('pointerup', (e) => {
    if (!isSliderDragging) return;
    e.stopPropagation();
    isSliderDragging = false;
    grapheneSliderThumb.releasePointerCapture(e.pointerId);
  });

  document.getElementById('graphene-slider-panel').addEventListener('pointerdown', (e) => {
    if (e.target === grapheneSliderThumb) return;
    const svgEl = document.getElementById('viewport');
    const pt = svgEl.createSVGPoint();
    pt.x = e.clientX;
    pt.y = 0;
    const svgP = pt.matrixTransform(svgEl.getScreenCTM().inverse());
    let localX = svgP.x - 250;
    if (localX >= SLIDER_MIN_X && localX <= SLIDER_MAX_X) {
      updateGrapheneSlider(e.clientX);
    }
  });

  // 3D drag rotation
  touchOverlay.addEventListener('pointerdown', e => {
    if (!touchMode || dataTableMode) return;
    isDragging = true; lastMouseX = e.clientX; lastMouseY = e.clientY;
    touchOverlay.setPointerCapture(e.pointerId);
    touchOverlay.style.cursor = 'grabbing';
  });
  touchOverlay.addEventListener('pointermove', e => {
    if (!isDragging) return;
    rotY += (e.clientX - lastMouseX) * 0.01;
    rotX += (e.clientY - lastMouseY) * 0.01;
    rotX = Math.max(-Math.PI / 2 + 0.05, Math.min(Math.PI / 2 - 0.05, rotX));
    lastMouseX = e.clientX; lastMouseY = e.clientY;
    scheduleDraw();
  });
  touchOverlay.addEventListener('pointerup', e => {
    isDragging = false; touchOverlay.releasePointerCapture(e.pointerId);
    touchOverlay.style.cursor = 'grab';
  });

  // ===== BOOT =====
  updateUI();
})();
